namespace OreumMok {partial class MainForm {
List<D> businessDefinitions=new List<D>();string businessKey="company";
void LoadBusinessMenus(){names["competitorPrices"]="타사 가격 비교";businessDefinitions=J.Rows(b.Call("businessCatalog"),"modules");names["lighting"]="조명 · 전기 시공";names["business"]="사업 운영 · 문서";names["reports"]="통계 · 보고서";}
bool HasBusiness(){return businessDefinitions.Any(x=>Can(J.Text(x,"key")+".read"));}
void BusinessWorkspace(){var choices=businessDefinitions.Where(x=>Can(J.Text(x,"key")+".read")).ToList();if(choices.Count==0){content.Controls.Add(new Label{Text="허용된 업무가 없습니다.",AutoSize=true});return;}if(!choices.Any(x=>J.Text(x,"key")==businessKey))businessKey=J.Text(choices[0],"key");var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=4,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,70));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);var select=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,Font=new Font(Font.FontFamily,13)};foreach(D d in choices)select.Items.Add(new Choice(J.Text(d,"key"),J.Text(d,"label")));for(int i=0;i<select.Items.Count;i++)if(((Choice)select.Items[i]).Id==businessKey)select.SelectedIndex=i;select.SelectedIndexChanged+=(o,e)=>{businessKey=((Choice)select.SelectedItem).Id;ShowPage("business");};layout.Controls.Add(select,0,0);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=false};layout.Controls.Add(bar,0,1);var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};D module=choices.First(x=>J.Text(x,"key")==businessKey);var fields=J.Rows(module,"fields");if(businessKey=="documents"){foreach(string label in new[]{"문서 번호","종류","현장","상태","이력 수"})g.Columns.Add(label,label);foreach(D row in J.Rows(state,"documents")){int i=g.Rows.Add(J.Text(row,"number"),J.Text(row,"kind"),RecordName("projects",J.Text(row,"project")),J.Text(row,"status"),J.Rows(row,"history").Count);g.Rows[i].Tag=row;}}else{var visible=fields.Take(6).ToList();foreach(D f in visible)g.Columns.Add(J.Text(f,"key"),J.Text(f,"label").Split('(')[0].Trim());if(businessKey=="paymentPlans"){g.Columns.Add("paid","정산액");g.Columns.Add("remaining","미정산");}if(businessKey=="lighting"){g.Columns.Add("quoteTotal","견적 합계");g.Columns.Add("plannedCost","예상 원가");g.Columns.Add("difference","예상 차액");g.Columns.Add("loadW","입력 부하 W");}if(businessKey=="labor")g.Columns.Add("planned","계획 비용");foreach(D row in J.Rows(state,businessKey)){var values=new List<object>();foreach(D f in visible){string k=J.Text(f,"key");values.Add(J.Text(f,"type")=="projects"?RecordName("projects",J.Text(row,k)):J.Text(f,"type")=="number"?J.Num(row,k).ToString("N0"):J.Text(row,k));}if(businessKey=="paymentPlans"){values.Add(J.Money(J.Num(row,"paid")));values.Add(J.Money(J.Num(row,"amount")-J.Num(row,"paid")));}if(businessKey=="lighting"){decimal cost=J.Num(row,"materialCost")+J.Num(row,"laborCost")+J.Num(row,"otherCost");values.Add(J.Money(J.Num(row,"supply")+J.Num(row,"tax")));values.Add(J.Money(cost));values.Add(J.Money(J.Num(row,"supply")-cost));values.Add(J.Num(row,"quantity")*J.Num(row,"watts")+J.Num(row,"length")*J.Num(row,"wattsPerM"));}if(businessKey=="labor")values.Add(J.Money(J.Num(row,"days")*J.Num(row,"rate")));int i=g.Rows.Add(values.ToArray());g.Rows[i].Tag=row;}}
if(businessKey=="lighting"){g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells;foreach(DataGridViewColumn col in g.Columns)col.MinimumWidth=110;}layout.Controls.Add(g,0,3);var searchBar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};searchBar.Controls.Add(new Label{Text="업무 검색",AutoSize=true,Margin=new Padding(3,10,6,0)});var businessSearch=new TextBox{Width=300,Name="businessSearch",AccessibleName="업무 목록 검색",Margin=new Padding(3,6,8,3)};searchBar.Controls.Add(businessSearch);var shownCount=new Label{AutoSize=true,Text="전체 "+g.Rows.Count+"건",Margin=new Padding(3,10,6,0)};searchBar.Controls.Add(shownCount);searchBar.Controls.Add(Style.Button("검색 지우기",(o,e)=>businessSearch.Clear()));layout.Controls.Add(searchBar,0,2);businessSearch.TextChanged+=(o,e)=>{string term=businessSearch.Text.Trim();g.CurrentCell=null;int shown=0;foreach(DataGridViewRow row in g.Rows){string value=String.Join(" ",row.Cells.Cast<DataGridViewCell>().Select(c=>Convert.ToString(c.Value)))+" "+new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(row.Tag);row.Visible=term.Length==0||value.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0;if(row.Visible)shown++;}shownCount.Text="검색 "+shown+" / 전체 "+g.Rows.Count+"건";};Func<D> current=()=>g.CurrentRow==null?null:g.CurrentRow.Tag as D;Action edit=()=>{D row=current();if(row!=null)EditBusiness(businessKey,row);};var add=Style.Button(businessKey=="documents"?"문서 발급":"새 항목",(o,e)=>{if(businessKey=="documents")NewDocument(null);else EditBusiness(businessKey,null);});add.Enabled=Can(businessKey+".write");bar.Controls.Add(add);bar.Controls.Add(Style.Button(businessKey=="documents"?"문서 보기":Can(businessKey+".write")?"열기 / 수정":"상세 보기",(o,e)=>{D row=current();if(row==null)return;if(businessKey=="documents")ViewBusinessDocument(row);else edit();}));if(businessKey=="documents"){bar.Controls.Add(Style.Button("재발행",(o,e)=>{if(current()!=null)NewDocument(current());}));bar.Controls.Add(Style.Button("문서 취소",(o,e)=>{D row=current();if(row==null||!Can("documents.write"))return;using(var f=new EditForm("문서 취소 · 이력 보존",J.Row("reason",""),new[]{new Field("reason","취소 사유","note")},null,x=>{try{b.Call("cancelDocument",J.Row("id",J.Text(row,"id"),"reason",J.Text(x,"reason"),"version",version));LoadState();ShowPage("business");return true;}catch(Exception ex){MessageBox.Show(ex.Message);return false;}}))f.ShowDialog(this);}));}else{var delete=Style.Button("삭제",(o,e)=>{D row=current();if(row==null||MessageBox.Show("선택 항목을 삭제할까요?","삭제",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;D next=J.Clone(state);next[businessKey]=J.Rows(next,businessKey).Where(x=>J.Text(x,"id")!=J.Text(row,"id")).ToArray();Commit(next);});delete.Enabled=Can(businessKey+".write")&&businessKey!="taxRecords";bar.Controls.Add(delete);}if(businessKey=="paymentPlans")bar.Controls.Add(Style.Button("수금 / 지급 반영",(o,e)=>{if(current()!=null)SettleBusiness(current());}));bar.Controls.Add(Style.Button("새로고침",(o,e)=>{LoadState();ShowPage("business");}));foreach(Button button in bar.Controls.OfType<Button>())if(new[]{"재발행","문서 취소"}.Contains(button.Text))button.Enabled=Can("documents.write");if(businessKey=="paymentPlans")bar.Controls.Add(Style.Button("정산 입력 정정",(o,e)=>{if(current()!=null)ReverseBusiness(current());}));g.DoubleClick+=(o,e)=>{if(businessKey=="documents"){if(current()!=null)ViewBusinessDocument(current());}else edit();};}
void EditBusiness(string key,D original){if(!Can(key+".write")){if(original!=null){D def=businessDefinitions.First(d=>J.Text(d,"key")==key);string text=String.Join("\r\n\r\n",J.Rows(def,"fields").Select(f=>J.Text(f,"label")+": "+(J.Text(f,"type")=="projects"?RecordName("projects",J.Text(original,J.Text(f,"key"))):J.Text(original,J.Text(f,"key")))));using(var view=new Form{Text="조회 전용 · "+J.Text(original,"name"),Width=800,Height=650}){Style.Form(view);view.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=text});view.ShowDialog(this);}}return;}D module=businessDefinitions.First(x=>J.Text(x,"key")==key);if(key=="company"&&original==null&&J.Rows(state,key).Count>0){MessageBox.Show("등록된 사업자 정보를 열어 수정하세요.");return;}D row=original==null?J.Row("id",Guid.NewGuid().ToString()):J.Clone(original);var fields=J.Rows(module,"fields").Select(f=>new Field(J.Text(f,"key"),J.Text(f,"label"),J.Text(f,"type"),J.Text(f,"options"))).ToArray();OpenWorkspace(new EditForm(J.Text(module,"label"),row,fields,J.Clone(state),WorkspaceCommit(key,original)));}
void NewDocument(D previous){if(!Can("documents.write")){MessageBox.Show("문서 발급 권한이 없습니다.");return;}using(var f=new EditForm("현장 정보에서 문서 생성",J.Row("requestId",Guid.NewGuid().ToString(),"project",previous==null?"":J.Text(previous,"project"),"kind",previous==null?"거래명세서":J.Text(previous,"kind"),"memo",""),new[]{new Field("project","연결 현장","projects"),new Field("kind","문서 종류","select","거래명세서,공사계약서,작업확인서,공사완료보고서,입금확인서,하자보수확인서"),new Field("memo","문서 조건 · 고객 확인","note")},state,row=>{try{if(!row.ContainsKey("requestId"))row["requestId"]=Guid.NewGuid().ToString();row["version"]=version;if(previous!=null)row["reissueOf"]=J.Text(previous,"id");D created=b.Call("createDocument",row);LoadState();ShowPage("business");ViewBusinessDocument(J.Obj(created["record"]));return true;}catch(Exception e){MessageBox.Show(e.Message);return false;}}))f.ShowDialog(this);}
void ViewBusinessDocument(D record){try{D result=b.Call("documentView",J.Row("id",J.Text(record,"id")));string[] lines=((System.Collections.IEnumerable)result["lines"]).Cast<object>().Select(Convert.ToString).ToArray();using(var form=new Form{Text=J.Text(record,"number")+" · 발급 기록",Width=950,Height=760}){Style.Form(form);var box=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Text=String.Join("\r\n\r\n",lines),Font=new Font(Font.FontFamily,12)};var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58};var print=Style.Button("인쇄 / PDF 저장",(o,e)=>{try{b.Call("documentView",J.Row("id",J.Text(record,"id"),"export",true));PrintBusinessLines(lines,J.Text(record,"number"));}catch(Exception ex){MessageBox.Show(ex.Message);}});print.Enabled=Can("export");bar.Controls.Add(print);form.Controls.Add(box);form.Controls.Add(bar);form.Shown+=(o,e)=>{box.SelectionStart=0;box.SelectionLength=0;box.BackColor=Color.White;};form.ShowDialog(this);}}catch(Exception e){MessageBox.Show(e.Message);}}
void PrintBusinessLines(string[] lines,string title){int index=0;List<string> wrapped=null;using(var doc=new PrintDocument()){doc.DocumentName=title;doc.BeginPrint+=(o,e)=>{index=0;wrapped=null;};doc.PrintPage+=(o,e)=>{using(var font=new Font(Premium.Family,10)){if(wrapped==null){wrapped=new List<string>();foreach(string raw in lines)foreach(string paragraph in (raw??"").Split('\n')){string rest=paragraph;if(rest.Length==0)wrapped.Add("");while(rest.Length>0){int n=rest.Length;while(n>1&&e.Graphics.MeasureString(rest.Substring(0,n),font).Width>e.MarginBounds.Width)n--;wrapped.Add(rest.Substring(0,n));rest=rest.Substring(n);}}}float y=e.MarginBounds.Top,lineHeight=font.GetHeight(e.Graphics)+7;while(index<wrapped.Count){if(y+lineHeight>e.MarginBounds.Bottom){e.HasMorePages=true;return;}e.Graphics.DrawString(wrapped[index++],font,Brushes.Black,e.MarginBounds.Left,y);y+=lineHeight;}}e.HasMorePages=false;};using(var preview=new PrintPreviewDialog{Document=doc,Width=1000,Height=800})preview.ShowDialog(this);}}

void SettleBusiness(D plan){if(!Can("paymentPlans.write")||!Can("projects.write")||!Can("transactions.write")){MessageBox.Show("계획·현장·입출금 이력 편집 권한이 필요합니다.");return;}using(var f=new EditForm("실제 수금 / 지급 반영 · 중복 요청 보호",J.Row("requestId",Guid.NewGuid().ToString(),"amount",J.Num(plan,"amount")-J.Num(plan,"paid"),"date",DateTime.Today.ToString("yyyy-MM-dd")),new[]{new Field("amount","실제 금액","number"),new Field("date","거래일","date")},null,x=>{try{x["id"]=J.Text(plan,"id");if(!x.ContainsKey("requestId"))x["requestId"]=Guid.NewGuid().ToString();x["version"]=version;b.Call("settlePlan",x);LoadState();ShowPage("business");return true;}catch(Exception e){MessageBox.Show(e.Message);return false;}}))f.ShowDialog(this);}
void ReportWorkspace(){try{D report=b.Call("businessReport");var panel=new Panel{Dock=DockStyle.Fill};content.Controls.Add(panel);var table=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};foreach(string label in new[]{"월","수금","현장 지출","공통경비","현금 잔액"})table.Columns.Add(label,label);foreach(D row in J.Rows(report,"months"))table.Rows.Add(J.Text(row,"month"),J.Money(J.Num(row,"receipts")),J.Money(J.Num(row,"expenses")),J.Money(J.Num(row,"overheads")),J.Money(J.Num(row,"cashBalance")));var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=125};bottom.Controls.Add(new Label{Text=J.Text(report,"note"),Width=900,Height=65,ForeColor=Style.Muted});bottom.Controls.Add(Style.Button("공사별 참고 손익",(o,e)=>{string text=String.Join("\r\n\r\n",J.Rows(report,"projects").Select(r=>J.Text(r,"name")+" / 매출 공급가 "+J.Money(J.Num(r,"revenue"))+" / 원가 "+J.Money(J.Num(r,"cost"))+" / 참고 이익 "+J.Money(J.Num(r,"profit"))+" / "+J.Text(r,"basis")+" / 과세 "+J.Text(r,"taxMode")));MessageBox.Show(text,"공사별 참고 손익");}));bottom.Controls.Add(Style.Button("CSV 내보내기",(o,e)=>{if(!Can("export")){MessageBox.Show("내보내기 권한이 없습니다.");return;}using(var f=new SaveFileDialog{Filter="CSV|*.csv",FileName="오름목-월별현금흐름.csv"})if(f.ShowDialog()==DialogResult.OK){var lines=new List<string>{"월,수금,현장지출,공통경비,현금잔액"};foreach(D r in J.Rows(report,"months"))lines.Add(String.Join(",",new[]{"month","receipts","expenses","overheads","cashBalance"}.Select(k=>J.Text(r,k))));File.WriteAllLines(f.FileName,lines,new System.Text.UTF8Encoding(true));}}));panel.Controls.Add(table);panel.Controls.Add(bottom);}catch(Exception e){content.Controls.Add(new Label{Text=e.Message,AutoSize=true});}}
void ReverseBusiness(D plan){if(!Can("paymentPlans.write")||!Can("projects.write")||!Can("transactions.write")){MessageBox.Show("정산 편집 권한이 필요합니다.");return;}var entries=J.Rows(state,"transactions").Where(t=>J.Text(t,"plan")==J.Text(plan,"id")&&J.Text(t,"status")!="취소").ToList();if(entries.Count==0){MessageBox.Show("정정할 정산 기록이 없습니다.");return;}string options=String.Join(",",entries.Select(t=>J.Text(t,"id")));using(var f=new EditForm("장부 입력 정정 · 실제 반환 처리가 아닙니다",J.Row("transaction",J.Text(entries[0],"id"),"reason",""),new[]{new Field("transaction","정정할 거래 번호","select",options),new Field("reason","정정 사유","note")},null,x=>{try{b.Call("reverseSettlement",J.Row("id",J.Text(x,"transaction"),"reason",J.Text(x,"reason"),"version",version));LoadState();ShowPage("business");return true;}catch(Exception e){MessageBox.Show(e.Message);return false;}}))f.ShowDialog(this);}
